import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addHours_TriageGen0Test {







    @Test
    public void testAddHours_DayRollover() {
        // Initialize with a known time: 2023-01-01 23:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 23, 0, 0, 0);
        int hoursToAdd = 2;

        dt.addHours(hoursToAdd);

        // Should roll over to next day
        assertEquals(1, dt.getDayOfMonth());
        assertEquals(2, dt.getDayOfMonth()); // Wait, 23 + 2 = 25 -> 01:00 next day
        assertEquals(1, dt.getHourOfDay());
        assertEquals(2, dt.getDayOfMonth());
    }


}

